#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/panel/card/card_values/card_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Card's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/card.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The padding, section gap and header and footer extents; a view. Until written the card follows its theme's layout (effective_card_layout); a write overrides it, and reset_card_layout_to_theme returns to the theme's. Values that are not finite or are unbounded throw std::invalid_argument.
template <typename Declaring>
struct CardCardLayoutCapability {
    PropertyView<CardLayout, CardCardLayoutCapability<Declaring>> card_layout;

    static void assign(CardCardLayoutCapability& capability, CardLayout incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.card_layout), std::move(incoming));
    }

    static CardLayout read(const CardCardLayoutCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        CardLayout current = control.read_view(capability.card_layout);
        return current;
    }
};

// Whether the card takes focus, the pointer and activation. Turning it off clears the hot, pressed and focused visuals.
template <typename Declaring>
struct CardInteractiveCapability {
    PropertyCell<bool, CardInteractiveCapability<Declaring>> interactive{};

    static void assign(CardInteractiveCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.interactive), incoming);
        if (!capability.interactive.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.interactive));
    }
};

// Whether the card is selected; a change raises selected_changed. selection_behavior decides whether activation writes it.
template <typename Declaring>
struct CardSelectedCapability {
    PropertyCell<bool, CardSelectedCapability<Declaring>> selected{};

    static void assign(CardSelectedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selected), incoming);
        if (!capability.selected.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selected));
    }
};

// Whether activation only notifies (manual, the default) or also selects or toggles the card before activated is raised. An undeclared value throws std::invalid_argument.
template <typename Declaring>
struct CardSelectionBehaviorPropertyCapability {
    PropertyCell<CardSelectionBehavior, CardSelectionBehaviorPropertyCapability<Declaring>> selection_behavior{CardSelectionBehavior::manual};

    static void assign(CardSelectionBehaviorPropertyCapability& capability, CardSelectionBehavior incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selection_behavior), incoming);
        if (!capability.selection_behavior.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selection_behavior));
    }
};

// Every Card capability, in the order the declaring class takes them.
template <typename Declaring>
struct CardCapabilities : public CardCardLayoutCapability<Declaring>,
                          public CardInteractiveCapability<Declaring>,
                          public CardSelectedCapability<Declaring>,
                          public CardSelectionBehaviorPropertyCapability<Declaring> {};

} // namespace gui_forms
